declaredPrintRule:
@media print {
  .brief-reading-finding { border-color: rgb(0, 0, 0); margin-bottom: 24px; }
  .brief-reading-section { margin-top: 32px; }
  .brief-reading-section > h2, .brief-reading-evidence > h2 { font-size: 18pt; }
  .brief-reading-section > h2, .brief-reading-evidence h2, .brief-reading-evidence h3 { break-after: avoid; }
  .brief-reading-finding blockquote p, .brief-reading-evidence blockquote p, .brief-reading-section > p { font-size: 11pt; line-height: 1.6; }
  .brief-reading-finding, .brief-reading-figure { break-inside: avoid; }
  .brief-reading-evidence > div { display: block; }
  .brief-reading-evidence > div > section + section { border-left: 0px; padding: 16px 0px 0px; }
}
